var turalyon = context.rulePiece;
if (!turalyon || turalyon.currentHp <= 0 || context.playerId !== turalyon.ownerPlayerId) return { success: false, message: '' };
if (['holy-smite', 'holy-heal', 'holy-charge'].indexOf(context.cardId) === -1) return { success: false, message: '' };
var turnNumber = battle.turn && battle.turn.turnNumber ? battle.turn.turnNumber : 0;
if (!battle.extensions) battle.extensions = {}; if (!battle.extensions.turalyonLightforgedTurns) battle.extensions.turalyonLightforgedTurns = {};
var firedTurns = battle.extensions.turalyonLightforgedTurns;
if (context.selectedOption === undefined && firedTurns[turalyon.instanceId] === turnNumber) return { success: false, message: '' };
function livingAt(x, y) { return battle.pieces.find(function(piece) { return piece.currentHp > 0 && piece.x === x && piece.y === y; }); }
function tileAt(x, y) { return battle.map.tiles.find(function(tile) { return tile.x === x && tile.y === y; }); }
var allies = battle.pieces.filter(function(piece) { return piece.currentHp > 0 && piece.ownerPlayerId === turalyon.ownerPlayerId && piece.x !== null && piece.y !== null; }).sort(function(a, b) { return a.instanceId < b.instanceId ? -1 : (a.instanceId > b.instanceId ? 1 : 0); });
var options = [];
allies.forEach(function(mover) {
  var maxDistance = (mover.moveRange || 0) + 2; var queue = [{ x: mover.x, y: mover.y, distance: 0 }]; var seen = {}; seen[mover.x + ',' + mover.y] = true;
  for (var qi = 0; qi < queue.length; qi++) { var current = queue[qi]; if (current.distance >= maxDistance) continue; var offsets = [[0, -1], [-1, 0], [1, 0], [0, 1]]; for (var oi = 0; oi < offsets.length; oi++) { var x = current.x + offsets[oi][0]; var y = current.y + offsets[oi][1]; var key = x + ',' + y; if (seen[key]) continue; seen[key] = true; var tile = tileAt(x, y); if (!tile || !tile.props || !tile.props.walkable) continue; var occupant = livingAt(x, y); if (occupant && occupant.ownerPlayerId !== mover.ownerPlayerId) continue; var nextDistance = current.distance + 1; queue.push({ x: x, y: y, distance: nextDistance }); if (!occupant) options.push({ label: (mover.name || mover.templateId) + ' -> (' + x + ',' + y + ')', value: { pieceId: mover.instanceId, x: x, y: y } }); } }
});
if (options.length === 0) { firedTurns[turalyon.instanceId] = turnNumber; return { success: false, message: '' }; }
options.unshift({ label: '放弃远征移动', value: 'skip' });
if (context.selectedOption === undefined) firedTurns[turalyon.instanceId] = turnNumber;
var choice = selectOption({ title: '圣铸进军：选择友方与落点', options: options });
if (choice === undefined || choice === null || choice.needsOptionSelection) return choice;
firedTurns[turalyon.instanceId] = turnNumber;
if (choice === 'skip') return { success: true, message: turalyon.name + '放弃了本回合的远征移动' };
var selected = options.find(function(option) { return option.value && option.value !== 'skip' && choice && option.value.pieceId === choice.pieceId && option.value.x === choice.x && option.value.y === choice.y; });
if (!selected) return { success: false, message: '选择的远征移动已失效' };
var mover = battle.pieces.find(function(piece) { return piece.instanceId === selected.value.pieceId && piece.currentHp > 0; });
if (!mover || livingAt(selected.value.x, selected.value.y)) return { success: false, message: '远征移动的落点已失效' };
mover.x = selected.value.x; mover.y = selected.value.y;
return { success: true, message: mover.name + '完成圣铸进军，移动至(' + mover.x + ',' + mover.y + ')' };
